package com.alpharip.staffmod.BuildTimelapse.ui;
import net.minecraft.client.gui.GuiButton;import net.minecraft.client.gui.GuiScreen;import java.io.IOException;
public final class BuildTimelapseStudioScreen extends GuiScreen {
 private final StudioController controller;private final StudioScreenModel model;private final com.alpharip.staffmod.BuildTimelapse.integration.BuildTimelapseRuntime runtime;private boolean navigating;
 public BuildTimelapseStudioScreen(StudioController c,StudioScreenModel m){this(c,m,null);}
 public BuildTimelapseStudioScreen(StudioController c,StudioScreenModel m,com.alpharip.staffmod.BuildTimelapse.integration.BuildTimelapseRuntime runtime){if(c==null||m==null)throw new IllegalArgumentException();controller=c;model=m;this.runtime=runtime;}
 @Override public boolean doesGuiPauseGame(){return false;}
 @Override public void initGui(){navigating=false;buttonList.clear();int cx=width/2,top=height/2-62;buttonList.add(new GuiButton(0,cx-125,top,120,20,"Start Recording"));buttonList.add(new GuiButton(1,cx+5,top,120,20,"Pause"));buttonList.add(new GuiButton(2,cx-125,top+25,120,20,"Resume"));buttonList.add(new GuiButton(3,cx+5,top+25,120,20,"Stop"));buttonList.add(new GuiButton(4,cx-125,top+58,80,20,"Camera"));buttonList.add(new GuiButton(5,cx-40,top+58,80,20,"Timeline"));buttonList.add(new GuiButton(6,cx+45,top+58,80,20,"Capture"));buttonList.add(new GuiButton(7,cx-60,top+86,120,20,"Save Project"));}
 @Override protected void actionPerformed(GuiButton b)throws IOException{if(b.id==0)controller.start();else if(b.id==1)controller.pause();else if(b.id==2)controller.resume();else if(b.id==3)controller.stop();else if(b.id==4){navigating=true;mc.displayGuiScreen(new CameraEditorScreen(this,controller.getCamera()));}else if(b.id==5){navigating=true;mc.displayGuiScreen(new com.alpharip.staffmod.RecordingStudio.ui.TimelineEditorScreen(this,controller.getTimeline()));}else if(b.id==6){navigating=true;mc.displayGuiScreen(new CaptureSettingsScreen(this,controller.getCaptureSettings()));}else if(b.id==7)controller.save();}
 @Override protected void keyTyped(char typedChar,int keyCode)throws IOException{if(keyCode==1){mc.displayGuiScreen(null);return;}super.keyTyped(typedChar,keyCode);}
 @Override public void onGuiClosed(){if(runtime!=null&&!navigating)runtime.shutdown();}
 @Override public void drawScreen(int mouseX,int mouseY,float partialTicks){drawDefaultBackground();drawCenteredString(fontRendererObj,"BUILD TIMELAPSE STUDIO",width/2,24,0xFFC83D);drawCenteredString(fontRendererObj,model.getProject()==null?"No project selected":model.getProject().getName(),width/2,42,0xFFFFFF);drawCenteredString(fontRendererObj,"Status: "+model.getStatus(),width/2,height/2+58,0xBBBBBB);super.drawScreen(mouseX,mouseY,partialTicks);}
}